const wh = $('Webhook Relance').first().json;
const body = wh.body || wh;
const lead = $input.first().json;
const merged = {
  ...body,
  lead_id: body.lead_id || lead.lead_id,
  phone: body.phone || lead.phone || '',
  first_name: body.first_name || lead.first_name || '',
  property_address: body.property_address || body.full_address || lead.property_address || '',
  neighborhood: body.neighborhood || lead.neighborhood || '',
  do_not_call: body.do_not_call || lead.immo_do_not_call,
  explicit_refusal: body.explicit_refusal || lead.immo_explicit_refusal,
  total_call_attempts: body.total_call_attempts ?? lead.immo_total_call_attempts ?? 0,
  last_call_timestamp: lead.immo_last_call_at || body.last_call_timestamp,
};
return [{ json: merged }];

const item = $input.first().json;
const body = item.body || item;
const {
  total_call_attempts = 0,
  last_call_timestamp,
  do_not_call,
  explicit_refusal
} = body;

if (do_not_call || explicit_refusal) {
  return [{ json: { ...body, action: 'STOP_ALL_CONTACT', reason: 'explicit_refusal_or_dnc' } }];
}

const maxDay = parseInt($env.MAX_CALLS_PER_DAY || '3', 10);
if (total_call_attempts >= maxDay && last_call_timestamp) {
  const hours = (Date.now() - new Date(last_call_timestamp)) / 3600000;
  if (hours < 24) {
    return [{ json: { ...body, action: 'WAIT', reason: 'max_daily_attempts', waitHours: 24 - hours } }];
  }
}

const maxTotal = parseInt($env.MAX_TOTAL_CALLS || '10', 10);
if (total_call_attempts >= maxTotal) {
  return [{ json: { ...body, action: 'ARCHIVE', reason: 'max_total_attempts' } }];
}

const startH = parseInt($env.CALL_START_HOUR || '8', 10);
const endH = parseInt($env.CALL_END_HOUR || '20', 10);
const nowStr = new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' });
const toronto = new Date(nowStr);
const h = toronto.getHours();
if (h < startH || h >= endH) {
  return [{ json: { ...body, action: 'WAIT', reason: 'outside_call_hours', torontoHour: h } }];
}

return [{ json: { ...body, action: 'PROCEED_TO_CALL' } }];

const body = $input.first().json;
const relance_number = parseInt(body.relance_number || 1, 10);
const agentMap = {
  1: $env.ELEVENLABS_AGENT_ID_RELANCE_J1,
  2: $env.ELEVENLABS_AGENT_ID_RELANCE_J3,
  3: $env.ELEVENLABS_AGENT_ID_RELANCE_J7,
  4: $env.ELEVENLABS_AGENT_ID_RELANCE_J14,
};
const optimalHours = { 1: 10, 2: 10, 3: 16, 4: 10 };
const nowStr = new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' });
const torontoHour = new Date(nowStr).getHours();
const torontoDay = new Date(nowStr).getDay();
const targetHour = optimalHours[relance_number] || 10;
const isOptimalWindow = (
  (torontoHour >= 10 && torontoHour < 11) ||
  (torontoHour >= 16 && torontoHour < 18)
);
function minutesToNext(hour) {
  if (hour < 10) return (10 - hour) * 60;
  if (hour >= 11 && hour < 16) return (16 - hour) * 60;
  if (hour >= 18) return ((24 - hour) + 10) * 60;
  return 0;
}
const first = (body.first_name || body.lead_name || 'there').split(' ')[0];
return [{
  json: {
    ...body,
    agent_id: agentMap[relance_number] || $env.ELEVENLABS_AGENT_ID_IMMO,
    agent_phone_number_id: $env.ELEVENLABS_PHONE_NUMBER_ID,
    optimal_call_hour: targetHour,
    isOptimalWindow,
    isBusinessDay: torontoDay >= 1 && torontoDay <= 6,
    delayMinutes: isOptimalWindow ? 0 : minutesToNext(torontoHour),
    callRecommendation: isOptimalWindow ? 'call_now' : 'schedule_later',
    dynamic_variables: {
      lead_name: first,
      property_address: body.property_address || body.full_address || '',
      days_since_request: String(body.days_since_request || 0),
      previous_call_attempts: String(body.previous_call_attempts || body.total_call_attempts || 0),
      previous_attempts: String(body.previous_call_attempts || 0),
      neighborhood: body.neighborhood || '',
      market_insight: body.market_insight || '',
      season: body.season || 'printemps',
      lead_id_odoo: String(body.lead_id || ''),
    }
  }
}];
